.toolbar.svelte-<scoped> {
  display: grid;
  gap: 0.75rem;
  grid-template-columns: minmax(16rem, 1fr) auto auto;
  align-items: end;
  padding: 1rem;
}

.dashboard.svelte-<scoped> {
  display: grid;
  grid-template-columns: repeat(4, minmax(12rem, 1fr));
  gap: 1rem;
  padding: 1rem;
}

.panel.svelte-<scoped> {
  border: 1px solid #cbd5e1;
  border-radius: 0.5rem;
  padding: 1rem;
}

.panel.active.svelte-<scoped> {
  border-color: #2563eb;
  background: #eff6ff;
}

.disabled.svelte-<scoped> {
  color: #64748b;
  padding: 2rem;
}
